import type { RouteKey, RouteParams, MaybeEmptyParamProp, AppRoute } from './types';
import type { NavigationOptions } from '../types/global.navigation';
type NavigationConfig<K extends RouteKey> = {
    key: K;
} & MaybeEmptyParamProp<RouteParams<K>>;
type NavigateByKey = <K extends RouteKey>(config: NavigationConfig<K>, options?: Pick<NavigationOptions, 'replace'>) => void;
type NavigateByAppRoute = (route: AppRoute, options?: Pick<NavigationOptions, 'replace'>) => void;
/**
 * Supports two calling forms:
 *  1. navigateToAppRoute({key: 'scientist', params: {id: 'dijkstra'}})
 *  2. navigateToAppRoute(
 *       createAppRoute({key: 'scientist', params: {id: 'dijkstra'}}),
 *     )
 */
type NavigateToAppRoute = NavigateByKey & NavigateByAppRoute;
type CreateAppRoute = <K extends RouteKey>(config: NavigationConfig<K>) => AppRoute;
type NavigationApis = {
    navigateToAppRoute: NavigateToAppRoute;
    createAppRoute: CreateAppRoute;
};
/**
 * Returns methods for navigating to full-page routes.
 *
 * @see https://docs.stripe.com/stripe-apps/routing
 */
export declare function useNavigation(): NavigationApis;
export {};
